sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {

    var grJournal = new GlideRecordSecure('sys_journal_field');
    grJournal.addQuery('element_id', current.sys_id);
    grJournal.addQuery('name', current.getTableName());
    grJournal.addQuery('element', 'comments');
    grJournal.orderByDesc('sys_created_on');
    grJournal.setLimit(2);
    grJournal.query();

    if (!grJournal.hasNext()) {
        template.print('<p>No comments available.</p>');
        return;
    }

    template.print('<table style="width:100%; border-collapse:collapse; font-family:Arial, sans-serif;">');

    while (grJournal.next()) {
        template.print(
            '<tr>' +
                '<td style="padding:12px; border:1px solid #ddd;">' +
                    '<div style="font-size:12px; color:#666; margin-bottom:6px;">' +
                        '<strong>' + grJournal.sys_created_by + '</strong>' +
                        ' | ' + grJournal.sys_created_on.getDisplayValue() +
                    '</div>' +
                    '<div style="font-size:14px; color:#333;">' +
                        GlideStringUtil.escapeHTML(grJournal.value.toString()).replace(/\n/g, '<br/>') +
                    '</div>' +
                '</td>' +
            '</tr>'
        );
    }

    template.print('</table>');

})(current, template, email, email_action, event);
